const uint[] SVO = uint[] (
    1u,2u,1u,0u,1u,0u,0u,0u,
    1u,1u,1u,256u,1u,256u,256u,0u,
    1u,1u,1u,257u,1u,257u,257u,0u,
    1u,1u,1u,258u,1u,258u,258u,0u,
    1u,1u,1u,259u,1u,259u,259u,0u,
    1u,1u,1u,260u,1u,260u,260u,0u
);
const vec3[] PALETTE = vec3[](
    vec3(0.0),
    vec3(1.0),
    vec3(1.0,0.0,0.0)
);

const uint SVO_ROOT = 5u;
const uint SVO_SIZE = 2u << SVO_ROOT;
const uint NUM_RESERVED_NODES = 256u;

// Ray-cube intersection function
bool rayCubeIntersect(vec3 ro, vec3 rd_inv, vec3 rd_flipped_sign, uvec3 corner, uint size, out float outTmin, out float tmax, out vec3 inNormal) {
    vec3 cubeMin = vec3(corner);
    vec3 cubeMax = vec3(corner+size);

    vec3 t0s = (cubeMin - ro) * rd_inv;
    vec3 t1s = (cubeMax - ro) * rd_inv;

    vec3 tsmaller = min(t0s, t1s);
    vec3 tbigger = max(t0s, t1s);

    float tmin = max(tsmaller.x, max(tsmaller.y, tsmaller.z));
    tmax = min(tbigger.x, min(tbigger.y, tbigger.z));

    bool intersection = tmax >= max(tmin, 0.0);

    // ensure that we don't have negative tmins!!!!!!!
    // I got majorly screwed over by this!!!!!
    outTmin = max(tmin,0.0);

    inNormal = vec3(equal(vec3(tmin), tsmaller)) * rd_flipped_sign;
    return intersection;
}

vec3 shade(vec3 base, vec3 hitPos, vec3 normal) {
    vec3 lightDir = normalize(vec3(5.0, 16.0, 7.5));
    float diff = max(dot(normal, lightDir), 0.0);
    return base * diff + vec3(0.1);
}

uint udot(uvec4 a, uvec4 b) {
    //return uint(dot(a,b);
    uvec4 sum = a * b;
    return sum.x + sum.y + sum.z + sum.a;
}

uint get_child(uvec4 node, uint size, vec3 pos, out uvec3 offset) {
    pos -= vec3(node.xyz);
    uint half_size_u = size / 2u;
    uvec3 gt = uvec3(greaterThanEqual(pos, vec3(half_size_u)));
    offset = gt * half_size_u;
    return SVO[udot(uvec4(gt, node.a), uvec4(1u,2u,4u,8u))];
}

vec3 trace(inout vec3 ro, inout vec3 rd) {
    float tmin, tmax;
    vec3 normal;

    vec3 rd_flipped_sign = -sign(rd);
    vec3 rd_inv = 1.0 / rd;

    uint size = SVO_SIZE;

    // stack items store node position and index.
    uvec4[32] stack;
    uint stack_len = 1u;
    stack[0] = uvec4(uvec3(0), SVO_ROOT);

    vec3 bg = vec3(0.3,0.3,0.7);

    for (int i=0; i<100;i++){
        if (stack_len==0u) {
            break;
        }

        uvec4 node = stack[stack_len-1u];

        bool intersects = rayCubeIntersect(ro, rd_inv, rd_flipped_sign, node.xyz, size, tmin, tmax, normal);

        if (!intersects) {
            stack_len -= 1u;
            size *= 2u;
            continue;
        }

        ro += rd * tmin;

        uvec3 offset;
        uint child = get_child(node, size, ro, offset);

        if (child >= NUM_RESERVED_NODES) {
            // head into child node.
            stack[stack_len] = uvec4(node.xyz + offset, child - NUM_RESERVED_NODES);
            stack_len += 1u;
            size /= 2u;
        } else if (child != 0u) {
            // hit solid node. shade.
            if (tmin == 0.0) {
                // Fix the normal for traces inside cubes or smth.
                intersects = rayCubeIntersect(ro, rd_inv, rd_flipped_sign, node.xyz + offset, size / 2u, tmin, tmax, normal);
            }
            return shade(PALETTE[child], ro, normal);
        } else {
            // Hit an air node. need to update ro to push the ray out of it.
            intersects = rayCubeIntersect(ro, rd_inv, rd_flipped_sign, node.xyz + offset, size / 2u, tmin, tmax, normal);
            ro += rd * (tmax+0.0001);
        }
    }
    return bg;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Screen coordinates
    vec2 uv = (fragCoord.xy / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    // Camera position (same angle as previous, using perspective projection)
    vec3 rayTarget = vec3(SVO_SIZE) / 2.0; // Looking at the cube's center
    vec3 ro = vec3(2.5, 2.5, 3.0) * rayTarget; // Camera position

    mat3 rotationMatrix = mat3(
        cos(iTime),  0.0, sin(iTime),
        0.0,         1.0, 0.0,
       -sin(iTime),  0.0, cos(iTime)
    );

    ro = rotationMatrix * ro;

    vec3 cameraForward = normalize(rayTarget - ro);
    vec3 cameraRight = normalize(cross(vec3(0.0, 1.0, 0.0), cameraForward)); // Right vector for camera
    vec3 cameraUp = cross(cameraForward, cameraRight); // Up vector for camera

    vec3 rd = normalize(cameraForward + uv.x * cameraRight + uv.y * cameraUp);
    fragColor.xyz = trace(ro, rd);
    fragColor.w = 1.0;
}
